package com.storemate.backend.web;
import com.storemate.backend.domain.*;import com.storemate.backend.repo.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.transaction.annotation.Transactional;import java.time.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest @Transactional class RetailServicesIntegrationTest {
 @Autowired InventoryController inventory;@Autowired InventoryOperationsController plans;@Autowired OrderFlowController flow;@Autowired StocktakeController stocktakes;@Autowired ShiftSummaryController summary;@Autowired StoreTaskController tasks;@Autowired HandoverController handovers;@Autowired StoreTemplateController templates;@Autowired AccountRepository accounts;@Autowired StoreRepository stores;@Autowired StoreMemberRepository members;@Autowired ProductRepository products;
 Account owner,staff,outsider;Store store;StoreMember person;
 @BeforeEach void setup(){String id=UUID.randomUUID().toString().substring(0,8);owner=accounts.save(new Account("retail-o"+id,"unused",Role.OWNER,"사장","20000101"));staff=accounts.save(new Account("retail-s"+id,"unused",Role.STAFF,"직원","20000101"));outsider=accounts.save(new Account("retail-x"+id,"unused",Role.STAFF,"외부","20000101"));store=stores.save(new Store("통합 서비스","카페",null,"주소",null,"09:00","22:00",id,owner));members.save(new StoreMember(owner,store,Role.OWNER,MemberStatus.APPROVED));person=members.save(new StoreMember(staff,store,Role.STAFF,MemberStatus.APPROVED));products.save(new Product(store,"ORDER-01","우유","음료",6,3,LocalDate.now().plusDays(2)));products.save(new Product(store,"ORDER-02","컵","소모품",2,3,null));}
 InventoryOperationsController.SavedPlan plan(){return plans.plan(owner,store.getId(),new InventoryOperationsController.PlanRequest("retail-plan-001",List.of(new InventoryOperationsController.PlanLine("ORDER-01",4,6,9))));}
 OrderFlowController.Receive received(String key,long revision,int qty){return new OrderFlowController.Receive(key,revision,List.of(new Dto.ReceiptItem("ORDER-01","입력명은 사용하지 않음",null,qty,LocalDate.now().plusDays(7).toString())));}
 StocktakeController.Save audit(String key,int first,int second,int expectedSecond){return new StocktakeController.Save(key,"마감 실사",List.of(new StocktakeController.Line("ORDER-01",6,first),new StocktakeController.Line("ORDER-02",expectedSecond,second)));}
 @Test void staffCanAdjustStockButCannotDeleteOrPlan(){inventory.update(staff,store.getId(),"ORDER-01",new Dto.UpdateProductRequest(null,5,null,6));assertEquals(5,inventory.one(owner,store.getId(),"ORDER-01").stock());assertThrows(ApiException.class,()->inventory.delete(staff,store.getId(),"ORDER-01",5));assertThrows(ApiException.class,()->plans.plan(staff,store.getId(),new InventoryOperationsController.PlanRequest("retail-staff-plan",List.of(new InventoryOperationsController.PlanLine("ORDER-01",3,5,9)))));assertThrows(ApiException.class,()->plans.recommendations(staff,store.getId()));assertFalse(plans.capabilities(staff,store.getId()).get("owner"));}
 @Test void staffCanRunStocktake(){stocktakes.save(staff,store.getId(),audit("retail-audit-001",5,2,2));assertEquals(5,inventory.one(owner,store.getId(),"ORDER-01").stock());}
 @Test void outsiderCannotUseInventory(){assertThrows(ApiException.class,()->plans.capabilities(outsider,store.getId()));assertThrows(ApiException.class,()->inventory.update(outsider,store.getId(),"ORDER-01",new Dto.UpdateProductRequest(null,1,null,6)));assertEquals(6,inventory.one(owner,store.getId(),"ORDER-01").stock());}
 @Test void onlyOwnerCanSubmitOrderPlan(){var p=plan();assertThrows(ApiException.class,()->flow.submit(staff,store.getId(),p.id(),new OrderFlowController.Revision(0)));assertEquals("ORDERED",flow.submit(owner,store.getId(),p.id(),new OrderFlowController.Revision(0)).status());}
 @Test void orderSubmissionDoesNotChangeStockAndCanBeRetried(){var p=plan();assertEquals("DRAFT",p.status());var ordered=flow.submit(owner,store.getId(),p.id(),new OrderFlowController.Revision(0));assertEquals("ORDERED",ordered.status());assertEquals(ordered.revision(),flow.submit(owner,store.getId(),p.id(),new OrderFlowController.Revision(0)).revision());assertEquals(6,inventory.one(owner,store.getId(),"ORDER-01").stock());}
 @Test void partialAndFinalReceiptsTrackRemainingAndStock(){var p=plan();flow.submit(owner,store.getId(),p.id(),new OrderFlowController.Revision(0));flow.receive(staff,store.getId(),p.id(),received("retail-delivery-01",1,2));var partial=flow.get(owner,store.getId(),p.id());assertEquals("PARTIAL",partial.status());assertEquals(2,partial.items().getFirst().received());assertEquals(8,inventory.one(owner,store.getId(),"ORDER-01").stock());flow.receive(staff,store.getId(),p.id(),received("retail-delivery-02",2,2));assertEquals("DELIVERED",flow.get(owner,store.getId(),p.id()).status());assertEquals(10,inventory.one(owner,store.getId(),"ORDER-01").stock());assertEquals(2,flow.list(owner,store.getId(),p.id()).size());}
 @Test void receiptRetryAfterPlanRevisionDoesNotReceiveTwice(){var p=plan();flow.submit(owner,store.getId(),p.id(),new OrderFlowController.Revision(0));var r=received("retail-delivery-03",1,2);var first=flow.receive(staff,store.getId(),p.id(),r);assertEquals(first.id(),flow.receive(staff,store.getId(),p.id(),r).id());assertEquals(8,inventory.one(owner,store.getId(),"ORDER-01").stock());assertThrows(ApiException.class,()->flow.receive(staff,store.getId(),p.id(),received("retail-delivery-03",1,1)));}
 @Test void unsubmittedExcessAndStaleReceiptsAreRejected(){var p=plan();assertThrows(ApiException.class,()->flow.receive(staff,store.getId(),p.id(),received("retail-delivery-04",0,1)));flow.submit(owner,store.getId(),p.id(),new OrderFlowController.Revision(0));assertThrows(ApiException.class,()->flow.receive(staff,store.getId(),p.id(),received("retail-delivery-05",1,5)));assertThrows(ApiException.class,()->flow.receive(staff,store.getId(),p.id(),received("retail-delivery-06",0,1)));assertThrows(ApiException.class,()->flow.receive(outsider,store.getId(),p.id(),received("retail-delivery-07",1,1)));assertEquals(6,inventory.one(owner,store.getId(),"ORDER-01").stock());}
 @Test void receiptCannotIncludeUnorderedProductsOrWrongStore(){var p=plan();flow.submit(owner,store.getId(),p.id(),new OrderFlowController.Revision(0));assertThrows(ApiException.class,()->flow.receive(staff,store.getId(),p.id(),new OrderFlowController.Receive("retail-delivery-08",1,List.of(new Dto.ReceiptItem("ORDER-02","컵",null,1,null)))));var s=stores.save(new Store("다른 매장","카페",null,"주소",null,"09:00","22:00","different",owner));members.save(new StoreMember(owner,s,Role.OWNER,MemberStatus.APPROVED));assertThrows(ApiException.class,()->flow.get(owner,s.getId(),p.id()));}
 @Test void stocktakeSavesMultipleCountsAndRetryOnlyOnce(){var r=audit("retail-stocktake-01",4,3,2);var first=stocktakes.save(owner,store.getId(),r);assertEquals(4,inventory.one(owner,store.getId(),"ORDER-01").stock());assertEquals(3,inventory.one(owner,store.getId(),"ORDER-02").stock());assertEquals(first.id(),stocktakes.save(owner,store.getId(),r).id());assertEquals(1,stocktakes.history(owner,store.getId()).size());assertThrows(ApiException.class,()->stocktakes.save(owner,store.getId(),audit("retail-stocktake-01",3,3,2)));}
 @Test void stocktakeChecksEverySnapshotBeforeMutatingAnyProduct(){assertThrows(ApiException.class,()->stocktakes.save(owner,store.getId(),audit("retail-stocktake-02",1,4,99)));assertEquals(6,inventory.one(owner,store.getId(),"ORDER-01").stock());assertEquals(2,inventory.one(owner,store.getId(),"ORDER-02").stock());assertTrue(stocktakes.history(owner,store.getId()).isEmpty());}
 @Test void stocktakeRejectsDuplicateProductsAndNegativeCounts(){assertThrows(ApiException.class,()->stocktakes.save(owner,store.getId(),new StocktakeController.Save("retail-stocktake-03","실사",List.of(new StocktakeController.Line("ORDER-01",6,1),new StocktakeController.Line("ORDER-01",6,2)))));assertThrows(ApiException.class,()->stocktakes.save(owner,store.getId(),audit("retail-stocktake-04",-1,2,2)));}
 @Test void unchangedStocktakeStillPreservesConfirmationRecord(){stocktakes.save(owner,store.getId(),audit("retail-stocktake-05",6,2,2));assertEquals(1,stocktakes.history(owner,store.getId()).size());assertEquals(6,inventory.one(owner,store.getId(),"ORDER-01").stock());}
 @Test void shiftSummaryKeepsReadAndApprovalIndependent(){var task=tasks.create(owner,store.getId(),new StoreTaskController.Create("retail-task-001","정리","설명",false,person.getId()));var memo=handovers.create(owner,store.getId(),new Dto.HandoverRequest("전달 사항",true,"긴급",task.id()));assertEquals(1,summary.get(staff,store.getId()).tasks().size());assertEquals(1,summary.get(staff,store.getId()).urgent().size());handovers.resolve(staff,store.getId(),memo.id(),new HandoverController.Resolve(true,0L));assertTrue(summary.get(staff,store.getId()).urgent().isEmpty());assertEquals(1,summary.get(staff,store.getId()).tasks().size());tasks.report(staff,store.getId(),task.id(),new StoreTaskController.Report(0L,"완료"));tasks.review(owner,store.getId(),task.id(),new StoreTaskController.Review(1L,true,"확인"));assertTrue(summary.get(staff,store.getId()).tasks().isEmpty());}
 @Test void shiftSummaryUsesExpiryTemplateAndStoreAccess(){assertEquals(1,summary.get(staff,store.getId()).expiry().size());var t=templates.get(owner,store.getId());templates.save(owner,store.getId(),new StoreTemplateController.Save(t.industry(),false,t.categories(),t.examples(),t.revision(),false));assertTrue(summary.get(staff,store.getId()).expiry().isEmpty());assertThrows(ApiException.class,()->summary.get(outsider,store.getId()));}
}
